  group.add(cabin);

  const roof = new THREE.Mesh(new THREE.BoxGeometry(width * 0.78, 0.12, van ? 2.8 : 1.7), paint);
  roof.position.set(0, van ? 1.71 : 1.37, cabin.position.z);
